const fs = require('fs');
const vm = require('vm');
const path = 'week02/teacher-baseline';
const ctx = vm.createContext({console, fetch: async () => { throw new Error('not used'); }, document: {getElementById: () => null}, window: {}, setTimeout});
vm.runInContext(fs.readFileSync(`${path}/data.js`, 'utf8'), ctx, {filename: 'data.js'});
vm.runInContext(fs.readFileSync(`${path}/script.js`, 'utf8'), ctx, {filename: 'script.js'});
const raw = fs.readFileSync(`${path}/u.item`, 'utf8');
vm.runInContext(`parseItemData(${JSON.stringify(raw)})`, ctx);
const report = vm.runInContext(`(() => {
  const recommend = id => {
    const liked = movies.find(m => m.id === id);
    const a = new Set(liked.genres);
    return movies.filter(m => m.id !== id).map((m, order) => {
      const b = new Set(m.genres);
      const intersection = new Set([...a].filter(x => b.has(x)));
      const union = new Set([...a, ...b]);
      return {...m, score: union.size ? intersection.size / union.size : 0, order};
    }).sort((x,y) => y.score-x.score).slice(0,2).map(({id,title,genres,score,order}) => ({id,title,genres,score,order}));
  };
  return {count: movies.length, toy: movies.find(m => m.id === 1), recommendations: {toy: recommend(1), starWars: recommend(50), fargo: recommend(100)}};
})()`, ctx);
const names = ['unknown','Action','Adventure','Animation',"Children's",'Comedy','Crime','Documentary','Drama','Fantasy','Film-Noir','Horror','Musical','Mystery','Romance','Sci-Fi','Thriller','War','Western'];
const rows = raw.trimEnd().split('\n').map(line => {
  const f = line.split('|');
  const flags = f.slice(5,24).map(Number);
  return {id:+f[0], title:f[1], flags, correctGenres:names.filter((_,i)=>flags[i]===1)};
});
const western = rows.filter(r => r.flags[18] === 1);
const westernOnly = western.filter(r => r.flags.reduce((a,b)=>a+b,0) === 1);
const unknown = rows.filter(r => r.flags[0] === 1);
console.log(JSON.stringify({...report, rawToy: rows.find(r=>r.id===1), westernCount:western.length, westernOnly:westernOnly.map(r=>({id:r.id,title:r.title})), unknownFlagged:unknown.map(r=>({id:r.id,title:r.title,correctGenres:r.correctGenres}))}, null, 2));
NODE
