                    // Calculate union
                    const union = new Set([...likedGenres, ...candidateGenres]);

                    // Calculate Jaccard similarity
                    const score = union.size > 0 ? intersection.size / union.size : 0;

                    return {
                        ...candidate,
                        score: score
                    };
                });

