<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Content-Based Movie Recommender</title>
    <link rel="stylesheet" href="style.css">
</head>
<body>
    <div class="container">
        <h1>Content-Based Movie Recommender</h1>
        <p>Compare recommendations from one movie with a three-movie taste profile.</p>

        <section class="feature-mode">
            <label for="feature-mode"><strong>Feature representation</strong></label>
            <select id="feature-mode">
                <option value="binary" selected>Binary genres — required cosine baseline</option>
                <option value="idf">IDF-weighted genres — experimental improvement</option>
            </select>
            <p>IDF weighting is optional and experimental; it gives rarer genres more weight.</p>
        </section>

        <section class="recommendation-mode">
            <h2>Item-to-Item Cosine</h2>
            <div class="controls">
                <select id="movie-select">
                    <option value="" disabled selected>Select an active movie</option>
                </select>
                <button onclick="getRecommendations()">Get Item Recommendations</button>
            </div>

            <div class="result-box">
                <p id="result">Please wait, loading data...</p>
            </div>
        </section>

        <section class="recommendation-mode">
            <h2>3-Movie Profile Cosine</h2>
            <div class="controls">
                <select id="profile-select-1">
                    <option value="" disabled selected>Select watched movie 1</option>
                </select>
                <select id="profile-select-2">
                    <option value="" disabled selected>Select watched movie 2</option>
                </select>
                <select id="profile-select-3">
                    <option value="" disabled selected>Select watched movie 3</option>
                </select>
                <button onclick="getProfileRecommendations()">Get Profile Recommendations</button>
            </div>

            <div class="result-box">
                <p id="profile-result">Select exactly three different watched movies.</p>
            </div>
        </section>
    </div>

    <script src="data.js"></script>
    <script src="script.js"></script>
</body>
</html>
// Global variables for storing movie and rating data
let movies = [];
let ratings = [];
let idfWeights = [];

// Genre names as defined in the u.item file
const genreNames = [
    "unknown", "Action", "Adventure", "Animation", "Children's", "Comedy",
    "Crime", "Documentary", "Drama", "Fantasy", "Film-Noir",
    "Horror", "Musical", "Mystery", "Romance", "Sci-Fi",
    "Thriller", "War", "Western"
];

// Primary function to load data from files
async function loadData() {
    try {
        // Load and parse movie data
        const moviesResponse = await fetch('u.item');
        if (!moviesResponse.ok) {
            throw new Error(`Failed to load movie data: ${moviesResponse.status}`);
        }
        const moviesText = await moviesResponse.text();
        parseItemData(moviesText);
        addIdfWeightedVectors();

        // Load and parse rating data
        const ratingsResponse = await fetch('u.data');
        if (!ratingsResponse.ok) {
            throw new Error(`Failed to load rating data: ${ratingsResponse.status}`);
        }
        const ratingsText = await ratingsResponse.text();
        parseRatingData(ratingsText);
    } catch (error) {
        console.error('Error loading data:', error);
        const resultElement = document.getElementById('result');
        if (resultElement) {
            resultElement.textContent = `Error: ${error.message}. Please make sure u.item and u.data files are in the correct location.`;
            resultElement.className = 'error';
        }
        throw error; // Re-throw to allow script.js to handle the error
    }
}

// Compute smoothed genre IDF values and retain both binary and weighted vectors
function addIdfWeightedVectors() {
    const movieCount = movies.length;
    const documentFrequencies = genreNames.map((_, index) =>
        movies.reduce((count, movie) => count + movie.genreVector[index], 0)
    );
    idfWeights = documentFrequencies.map(
        frequency => Math.log((movieCount + 1) / (frequency + 1)) + 1
    );

    movies.forEach(movie => {
        movie.weightedGenreVector = movie.genreVector.map(
            (value, index) => value * idfWeights[index]
        );
    });
}

// Parse movie data from u.item format
function parseItemData(text) {
    const lines = text.split('\n');

    for (const line of lines) {
        if (line.trim() === '') continue;

        const fields = line.split('|');
        if (fields.length < 5) continue; // Skip invalid lines

        const id = parseInt(fields[0]);
        const title = fields[1];

        // Extract genres (last 19 fields)
        const genreVector = fields.slice(5, 24).map(value => parseInt(value));
        const genres = genreNames.filter((_, index) => genreVector[index] === 1);

        movies.push({ id, title, genres, genreVector });
    }
}

// Parse rating data from u.data format
function parseRatingData(text) {
    const lines = text.split('\n');

    for (const line of lines) {
        if (line.trim() === '') continue;

        const fields = line.split('\t');
        if (fields.length < 4) continue; // Skip invalid lines

        const userId = parseInt(fields[0]);
        const itemId = parseInt(fields[1]);
        const rating = parseFloat(fields[2]);
        const timestamp = parseInt(fields[3]);

        ratings.push({ userId, itemId, rating, timestamp });
    }
}
// Initialize the application when the window loads
window.onload = async function() {
    try {
        // Display loading message
        const resultElement = document.getElementById('result');
        resultElement.textContent = "Loading movie data...";
        resultElement.className = 'loading';

        // Load data
        await loadData();

        // Populate dropdown and update status
        populateMoviesDropdowns();
        resultElement.textContent = "Data loaded. Please select a movie.";
        resultElement.className = 'success';
    } catch (error) {
        console.error('Initialization error:', error);
        // Error message already set in data.js
    }
};

// Populate the movies dropdown with sorted movie titles
function populateMoviesDropdowns() {
    // Sort movies alphabetically by title
    const sortedMovies = [...movies].sort((a, b) => a.title.localeCompare(b.title));
    const selectIds = ['movie-select', 'profile-select-1', 'profile-select-2', 'profile-select-3'];

    selectIds.forEach(selectId => {
        const selectElement = document.getElementById(selectId);
        while (selectElement.options.length > 1) {
            selectElement.remove(1);
        }

        sortedMovies.forEach(movie => {
            const option = document.createElement('option');
            option.value = movie.id;
            option.textContent = movie.title;
            selectElement.appendChild(option);
        });
    });
}

// Calculate cosine similarity between two numeric feature vectors
function cosineSimilarity(vectorA, vectorB) {
    const dotProduct = vectorA.reduce(
        (sum, value, index) => sum + value * vectorB[index],
        0
    );
    const normA = Math.sqrt(vectorA.reduce((sum, value) => sum + value * value, 0));
    const normB = Math.sqrt(vectorB.reduce((sum, value) => sum + value * value, 0));

    return normA > 0 && normB > 0 ? dotProduct / (normA * normB) : 0;
}

// Score candidates and preserve source order when cosine scores tie
function rankMovies(queryVector, excludedMovieIds, vectorProperty = 'genreVector') {
    return movies
        .filter(movie => !excludedMovieIds.has(movie.id))
        .map(candidate => ({
            ...candidate,
            score: cosineSimilarity(queryVector, candidate[vectorProperty])
        }))
        .sort((a, b) => {
            const difference = b.score - a.score;
            return Math.abs(difference) > 1e-12 ? difference : 0;
        })
        .slice(0, 5);
}

function getFeatureMode() {
    const useIdf = document.getElementById('feature-mode').value === 'idf';
    return {
        label: useIdf ? 'Experimental IDF-weighted cosine' : 'Binary cosine',
        vectorProperty: useIdf ? 'weightedGenreVector' : 'genreVector'
    };
}

function formatRecommendations(recommendations) {
    return recommendations
        .map(movie => `${movie.title} (${movie.score.toFixed(3)})`)
        .join(', ');
}

// Main recommendation function
function getRecommendations() {
    const resultElement = document.getElementById('result');

    try {
        // Step 1: Get user input
        const selectElement = document.getElementById('movie-select');
        const selectedMovieId = parseInt(selectElement.value);

        if (isNaN(selectedMovieId)) {
            resultElement.textContent = "Please select a movie first.";
            resultElement.className = 'error';
            return;
        }

        // Step 2: Find the liked movie
        const likedMovie = movies.find(movie => movie.id === selectedMovieId);
        if (!likedMovie) {
            resultElement.textContent = "Error: Selected movie not found in database.";
            resultElement.className = 'error';
            return;
        }

        // Show loading message while processing
        resultElement.textContent = "Calculating recommendations...";
        resultElement.className = 'loading';

        // Use setTimeout to allow the UI to update before heavy computation
        setTimeout(() => {
            try {
                const featureMode = getFeatureMode();
                const topRecommendations = rankMovies(
                    likedMovie[featureMode.vectorProperty],
                    new Set([likedMovie.id]),
                    featureMode.vectorProperty
                );

                // Step 7: Display results
                if (topRecommendations.length > 0) {
                    resultElement.textContent = `${featureMode.label} — because you liked "${likedMovie.title}", we recommend: ${formatRecommendations(topRecommendations)}`;
                    resultElement.className = 'success';
                } else {
                    resultElement.textContent = `No recommendations found for "${likedMovie.title}".`;
                    resultElement.className = 'error';
                }
            } catch (error) {
                console.error('Error in recommendation calculation:', error);
                resultElement.textContent = "An error occurred while calculating recommendations.";
                resultElement.className = 'error';
            }
        }, 100);
    } catch (error) {
        console.error('Error in getRecommendations:', error);
        resultElement.textContent = "An unexpected error occurred.";
        resultElement.className = 'error';
    }
}

// Recommend from the element-wise average of exactly three watched movies
function getProfileRecommendations() {
    const resultElement = document.getElementById('profile-result');
    const selectedIds = [1, 2, 3].map(index =>
        parseInt(document.getElementById(`profile-select-${index}`).value)
    );

    if (selectedIds.some(id => isNaN(id)) || new Set(selectedIds).size !== 3) {
        resultElement.textContent = "Please select exactly three different watched movies.";
        resultElement.className = 'error';
        return;
    }

    const watchedMovies = selectedIds.map(id => movies.find(movie => movie.id === id));
    if (watchedMovies.some(movie => !movie)) {
        resultElement.textContent = "Error: A selected movie was not found.";
        resultElement.className = 'error';
        return;
    }

    const featureMode = getFeatureMode();
    const profileVector = genreNames.map((_, index) =>
        watchedMovies.reduce(
            (sum, movie) => sum + movie[featureMode.vectorProperty][index],
            0
        ) / 3
    );
    const topRecommendations = rankMovies(
        profileVector,
        new Set(selectedIds),
        featureMode.vectorProperty
    );

    resultElement.textContent = `${featureMode.label} — from your 3-movie profile, we recommend: ${formatRecommendations(topRecommendations)}`;
    resultElement.className = 'success';
}

