  1	// Global variables for storing movie and rating data
  2	let movies = [];
  3	let ratings = [];
  4	let idfWeights = [];
  5	
  6	// Genre names as defined in the u.item file
  7	const genreNames = [
  8	    "unknown", "Action", "Adventure", "Animation", "Children's", "Comedy",
  9	    "Crime", "Documentary", "Drama", "Fantasy", "Film-Noir",
 10	    "Horror", "Musical", "Mystery", "Romance", "Sci-Fi",
 11	    "Thriller", "War", "Western"
 12	];
 13	
 14	// Primary function to load data from files
 15	async function loadData() {
 16	    try {
 17	        // Load and parse movie data
 18	        const moviesResponse = await fetch('u.item');
 19	        if (!moviesResponse.ok) {
 20	            throw new Error(`Failed to load movie data: ${moviesResponse.status}`);
 21	        }
 22	        const moviesText = await moviesResponse.text();
 23	        parseItemData(moviesText);
 24	        addIdfWeightedVectors();
 25	
 26	        // Load and parse rating data
 27	        const ratingsResponse = await fetch('u.data');
 28	        if (!ratingsResponse.ok) {
 29	            throw new Error(`Failed to load rating data: ${ratingsResponse.status}`);
 30	        }
 31	        const ratingsText = await ratingsResponse.text();
 32	        parseRatingData(ratingsText);
 33	    } catch (error) {
 34	        console.error('Error loading data:', error);
 35	        const resultElement = document.getElementById('result');
 36	        if (resultElement) {
 37	            resultElement.textContent = `Error: ${error.message}. Please make sure u.item and u.data files are in the correct location.`;
 38	            resultElement.className = 'error';
 39	        }
 40	        throw error; // Re-throw to allow script.js to handle the error
 41	    }
 42	}
 43	
 44	// Compute smoothed genre IDF values and retain both binary and weighted vectors
 45	function addIdfWeightedVectors() {
 46	    const movieCount = movies.length;
 47	    const documentFrequencies = genreNames.map((_, index) =>
 48	        movies.reduce((count, movie) => count + movie.genreVector[index], 0)
 49	    );
 50	    idfWeights = documentFrequencies.map(
 51	        frequency => Math.log((movieCount + 1) / (frequency + 1)) + 1
 52	    );
 53	
 54	    movies.forEach(movie => {
 55	        movie.weightedGenreVector = movie.genreVector.map(
 56	            (value, index) => value * idfWeights[index]
 57	        );
 58	    });
 59	}
 60	
 61	// Parse movie data from u.item format
 62	function parseItemData(text) {
 63	    const lines = text.split('\n');
 64	    
 65	    for (const line of lines) {
 66	        if (line.trim() === '') continue;
 67	        
 68	        const fields = line.split('|');
 69	        if (fields.length < 5) continue; // Skip invalid lines
 70	        
 71	        const id = parseInt(fields[0]);
 72	        const title = fields[1];
 73	        
 74	        // Extract genres (last 19 fields)
 75	        const genreVector = fields.slice(5, 24).map(value => parseInt(value));
 76	        const genres = genreNames.filter((_, index) => genreVector[index] === 1);
 77	        
 78	        movies.push({ id, title, genres, genreVector });
 79	    }
 80	}
 81	
 82	// Parse rating data from u.data format
 83	function parseRatingData(text) {
 84	    const lines = text.split('\n');
 85	    
 86	    for (const line of lines) {
 87	        if (line.trim() === '') continue;
 88	        
 89	        const fields = line.split('\t');
 90	        if (fields.length < 4) continue; // Skip invalid lines
 38	            selectElement.appendChild(option);
 39	        });
 40	    });
 41	}
 42	
 43	// Calculate cosine similarity between two numeric feature vectors
 44	function cosineSimilarity(vectorA, vectorB) {
 45	    const dotProduct = vectorA.reduce(
 46	        (sum, value, index) => sum + value * vectorB[index],
 47	        0
 48	    );
 49	    const normA = Math.sqrt(vectorA.reduce((sum, value) => sum + value * value, 0));
 50	    const normB = Math.sqrt(vectorB.reduce((sum, value) => sum + value * value, 0));
 51	
 52	    return normA > 0 && normB > 0 ? dotProduct / (normA * normB) : 0;
 53	}
 54	
 55	// Score candidates and preserve source order when cosine scores tie
 56	function rankMovies(queryVector, excludedMovieIds, vectorProperty = 'genreVector') {
 57	    return movies
 58	        .filter(movie => !excludedMovieIds.has(movie.id))
 59	        .map(candidate => ({
 60	            ...candidate,
 61	            score: cosineSimilarity(queryVector, candidate[vectorProperty])
 62	        }))
 63	        .sort((a, b) => {
 64	            const difference = b.score - a.score;
 65	            return Math.abs(difference) > 1e-12 ? difference : 0;
 66	        })
 67	        .slice(0, 5);
 68	}
 69	
 70	function getFeatureMode() {
 71	    const useIdf = document.getElementById('feature-mode').value === 'idf';
 72	    return {
 73	        label: useIdf ? 'Experimental IDF-weighted cosine' : 'Binary cosine',
 74	        vectorProperty: useIdf ? 'weightedGenreVector' : 'genreVector'
 75	    };
 76	}
 77	
 78	function formatRecommendations(recommendations) {
 79	    return recommendations
 80	        .map(movie => `${movie.title} (${movie.score.toFixed(3)})`)
 81	        .join(', ');
 82	}
 83	
 84	// Main recommendation function
 85	function getRecommendations() {
 86	    const resultElement = document.getElementById('result');
 87	    
 88	    try {
