 90	        const selectElement = document.getElementById('movie-select');
 91	        const selectedMovieId = parseInt(selectElement.value);
 92	        
 93	        if (isNaN(selectedMovieId)) {
 94	            resultElement.textContent = "Please select a movie first.";
