101	        if (!likedMovie) {
102	            resultElement.textContent = "Error: Selected movie not found in database.";
103	            resultElement.className = 'error';
104	            return;
105	        }
106	        
107	        // Show loading message while processing
108	        resultElement.textContent = "Calculating recommendations...";
109	        resultElement.className = 'loading';
110	        
111	        // Use setTimeout to allow the UI to update before heavy computation
112	        setTimeout(() => {
113	            try {
114	                const featureMode = getFeatureMode();
115	                const topRecommendations = rankMovies(
116	                    likedMovie[featureMode.vectorProperty],
117	                    new Set([likedMovie.id]),
118	                    featureMode.vectorProperty
119	                );
120	                
121	                // Step 7: Display results
122	                if (topRecommendations.length > 0) {
123	                    resultElement.textContent = `${featureMode.label} — because you liked "${likedMovie.title}", we recommend: ${formatRecommendations(topRecommendations)}`;
124	                    resultElement.className = 'success';
125	                } else {
126	                    resultElement.textContent = `No recommendations found for "${likedMovie.title}".`;
127	                    resultElement.className = 'error';
128	                }
129	            } catch (error) {
130	                console.error('Error in recommendation calculation:', error);
131	                resultElement.textContent = "An error occurred while calculating recommendations.";
132	                resultElement.className = 'error';
133	            }
134	        }, 100);
135	    } catch (error) {
136	        console.error('Error in getRecommendations:', error);
137	        resultElement.textContent = "An unexpected error occurred.";
138	        resultElement.className = 'error';
139	    }
140	}
141	
142	// Recommend from the element-wise average of exactly three watched movies
143	function getProfileRecommendations() {
144	    const resultElement = document.getElementById('profile-result');
145	    const selectedIds = [1, 2, 3].map(index =>
146	        parseInt(document.getElementById(`profile-select-${index}`).value)
147	    );
148	
149	    if (selectedIds.some(id => isNaN(id)) || new Set(selectedIds).size !== 3) {
150	        resultElement.textContent = "Please select exactly three different watched movies.";
151	        resultElement.className = 'error';
152	        return;
153	    }
154	
155	    const watchedMovies = selectedIds.map(id => movies.find(movie => movie.id === id));
156	    if (watchedMovies.some(movie => !movie)) {
157	        resultElement.textContent = "Error: A selected movie was not found.";
158	        resultElement.className = 'error';
159	        return;
160	    }
161	
162	    const featureMode = getFeatureMode();
163	    const profileVector = genreNames.map((_, index) =>
164	        watchedMovies.reduce(
165	            (sum, movie) => sum + movie[featureMode.vectorProperty][index],
166	            0
167	        ) / 3
168	    );
169	    const topRecommendations = rankMovies(
170	        profileVector,
171	        new Set(selectedIds),
172	        featureMode.vectorProperty
173	    );
174	
175	    resultElement.textContent = `${featureMode.label} — from your 3-movie profile, we recommend: ${formatRecommendations(topRecommendations)}`;
176	    resultElement.className = 'success';
177	}
